//! JC028's explicit transformation retains printed identity; it is not another blood card.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use std::{collections::BTreeSet,sync::OnceLock};
pub(crate) const ID:&str="JC028";
pub(crate) const FORM:&str="JC028:blood-form";
pub(crate) const KEY:&str="jc028-sacrifice-blood";
#[derive(Clone,Debug,PartialEq,Eq,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BloodOrigin{pub old_instance:String,pub grave_instance:String,pub owner:usize}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn host()->TargetSlotSpec{let mut t=target(Zone::Board,EntityKind::Character,Relation::Any,Range::Anywhere);t.subtype=Some("吸血鬼".into());t}
pub(crate) fn definition()->Definition{let mut a=ability(KEY,"牺牲鲜血奴仆：原实体成为鲜血结附目标吸血鬼",Timing::Fast,vec![Cost::JC028Sacrifice],vec![host()],vec![Op::JC028Blood],None);a.activation_only=true;with_abilities(vec![a])}
pub(crate) fn form_definition()->Definition{let mut d=attachment_definition(host());d.abilities.clear();let a=d.attachment.as_mut().unwrap();a.host_icons.combat=1;a.host_defense_bonus=1;d}
pub(crate) fn form_card()->&'static catalog::CardDefinition{static C:OnceLock<catalog::CardDefinition>=OnceLock::new();C.get_or_init(||{let mut d=catalog::card(ID).clone();d.name="鲜血".into();d.kind="attachment".into();d.additional_kinds.clear();d.defense=None;d.permanent_icons=Icons::default();d.temporary_icons=Icons::default();d.abilities.clear();d.rule_traits=form_definition().traits;d.text="受此结附的角色获得+1防御和额外的永久战斗1。".into();d})}
fn owns(o:&Op)->bool{match o{Op::JC028Blood=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key==KEY||a.costs.iter().any(|c|matches!(c,Cost::JC028Sacrifice))||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
fn related_frame(f:&ResolutionFrame)->bool{f.ability_key==KEY||f.steps.iter().any(|s|owns(&s.op))||f.already_paid.iter().any(|p|matches!(p,PaidCost::JC028Sacrificed(_)))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!same(a,&definition().abilities[0]){return Err("鲜血奴仆须保留牺牲、吸血鬼目标和原变形程序".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if matches!(id,ID|FORM)||d.abilities.iter().any(related){let expected=if id==FORM{form_definition()}else{definition()};if !matches!(id,ID|FORM)||!same(d,&expected){return Err("鲜血奴仆角色及附属形态不可移植或改写".into());}}Ok(())}
impl Game{
 pub(crate) fn jc028_pay(&mut self,actor:usize,s:&SourceSnapshot,a:&Action)->RuleResult<PaidCost>{if *a!=(Action{card_id:Some(s.card.id.clone()),ability_id:Some(KEY.into()),target_id:a.target_id.clone(),..Action::new("activate")}){return Err("鲜血奴仆行动不能夹带额外载荷".into());}if s.card.definition!=ID||s.card.face_down||s.card.controller!=actor||!self.board(&s.card.id).is_some_and(|(_,c)|same(c,&s.card)){return Err("鲜血奴仆须牺牲实际本方明置来源".into());}let receipts=self.remove_death_batch_with_receipts(vec![(s.card.id.clone(),RemovalCause::Sacrifice,s.clone())]);let receipt=receipts.into_iter().find(|r|r.old_instance==s.card.id).ok_or("鲜血奴仆牺牲缺少实际离场回执")?;Ok(PaidCost::JC028Sacrificed(receipt))}
 pub(crate) fn validate_jc028_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if f.source.card.definition==FORM{return Err("鲜血附属不保留角色能力".into());}if !related_frame(f){if f.source.card.definition==ID&&!matches!(f.ability_key.as_str(),"deploy"|"reveal")&&!self.validated_cross_card_frame(f)?{return Err("鲜血奴仆不能伪造外来帧".into());}return Ok(());}let s=&f.source;let c=&s.card;let [PaidCost::JC028Sacrificed(p)]=f.already_paid.as_slice()else{return Err("鲜血奴仆缺少原牺牲回执".into());};if c.definition!=ID||c.face_down||c.blood_origin.is_some()||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||f.ability_key!=KEY||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||p.old_instance!=c.id||p.owner!=c.owner||p.deferred_death.is_some()||!self.mystic_instance_number(&p.grave_instance).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||self.batch3_physical_cards().any(|now|now.id==c.id)||!f.resource_payments.is_empty()||f.chosen_region.is_some()||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||!same(&f.steps,&vec![Step{context:f.actor,op:Op::JC028Blood}])||f.targets.len()!=1{return Err("鲜血奴仆程序、费用或原来源损坏".into());}let t=&f.targets[0];if !same(&t.spec,&host())||!self.mystic_instance_valid(&t.id)||t.region_instance.is_some()||t.public.instance_id!=t.id||t.public.kind!="character"||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some(){return Err("鲜血奴仆原吸血鬼目标损坏".into());}self.mobility_immutable_identity(c)}
 pub(crate) fn jc028_blood(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_jc028_frame(f)?;if f.cursor!=1{return Err("鲜血奴仆变形未经过原目标守卫".into());}let PaidCost::JC028Sacrificed(p)=&f.already_paid[0]else{unreachable!()};if self.players[f.actor].eliminated||!self.valid_bound_target(f.actor,&f.source,&f.targets[0]){return Ok(());}if !self.bq095_destination_cards(p.owner).iter().any(|c|c.id==p.grave_instance&&c.definition==ID&&c.owner==p.owner){return Ok(());}let c=self.bq095_take_destination(p.owner,&p.grave_instance)?;let mut c=self.reset_zone_card(c);c.definition=FORM.into();c.controller=f.actor;c.blood_origin=Some(BloodOrigin{old_instance:p.old_instance.clone(),grave_instance:p.grave_instance.clone(),owner:p.owner});let id=c.id.clone();self.attachments.push(Attachment{card:c,host_id:f.targets[0].id.clone()});self.enter_triggers(f.actor,FORM,&id,false);Ok(())}
 pub(crate) fn validate_jc028_identity(&self,c:&Card)->RuleResult<()>{match(&c.blood_origin,c.definition.as_str()){(None,FORM)=>return Err("鲜血形态缺少实际牺牲身份".into()),(Some(o),FORM)=>{let number=|id:&str|self.mystic_instance_number(id);if c.face_down||o.owner!=c.owner||c.owner>=self.players.len()||c.generated.is_some()||!number(&o.old_instance).zip(number(&o.grave_instance)).is_some_and(|(a,b)|a<b)||!number(&o.grave_instance).zip(number(&c.id)).is_some_and(|(a,b)|a<b){return Err("鲜血形态原实体身份损坏".into());}},(Some(_),_)=>return Err("鲜血形态不能移植到其他牌面".into()),_=>()}Ok(())}
 pub(crate) fn validate_jc028_state(&self)->RuleResult<()>{let mut origins=BTreeSet::new();let mut paid_sources=BTreeSet::new();for c in self.batch3_physical_cards(){self.validate_jc028_identity(c)?;if let Some(o)=&c.blood_origin{if !origins.insert(&o.old_instance)||!self.attachments.iter().any(|a|std::ptr::eq(&a.card,c)){return Err("鲜血形态重复或进入非场上附属区".into());}}}for i in &self.stack{self.validate_jc028_play(i)?;if let Some(f)=&i.frame{self.validate_jc028_frame(f)?;if related_frame(f)&&!paid_sources.insert(&f.source.card.id){return Err("鲜血奴仆同次牺牲不能重复承载".into());}if related_frame(f)&&(i.id!=f.frame_id||i.controller!=f.actor||i.card.is_some()||i.reveal||i.deploy_region.is_some()||i.target!=f.targets.first().map(|t|t.id.clone())||f.cursor!=0){return Err("鲜血奴仆能力外壳损坏".into());}}}for e in &self.effects{match e{Effect::Declare{declaration:d}if related(&d.ability)||matches!(d.source.card.definition.as_str(),ID|FORM)&&!self.validated_cross_card_declaration(d)?=>return Err("鲜血奴仆不是自动触发".into()),Effect::Frame{frame:f}if related_frame(f)=>return Err("鲜血奴仆没有游离续体".into()),_=>()}}if self.pending.as_ref().is_some_and(|p|match &p.resolution{ChoiceResolution::Declare{declaration:d,..}=>related(&d.ability),ChoiceResolution::Frame{frame:f,..}=>related_frame(f),_=>false}){return Err("鲜血奴仆没有帧内待选".into());}Ok(())}
}
impl Game{
 pub(crate) fn validate_jc028_play(&self,item:&StackItem)->RuleResult<()>{
  if !item.card.as_ref().is_some_and(|c|c.definition==ID)&&!item.frame.as_ref().is_some_and(|f|f.source.card.definition==ID&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){return Ok(());}
  let f=item.frame.as_ref().ok_or("JC028角色事务缺少原帧")?;let c=&f.source.card;
  if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)
   ||f.source.region.is_none_or(|r|r>=self.regions.len())||f.source.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))
   ||f.source.attachment_host_instance.is_some()||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()
   ||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||f.chosen_region!=f.source.region
   ||!matches!(f.ability_key.as_str(),"deploy"|"reveal")||f.ability_key=="deploy"&&(c.face_down||!f.source.valid_character_play())||f.ability_key=="reveal"&&(!c.face_down||f.source.play_source.is_some())
   ||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=1&&ids.iter().all(|id|self.mystic_instance_valid(id)&&*id!=c.id)&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len())
   ||item.id!=f.frame_id||item.controller!=f.actor||item.target.is_some()||item.reveal!=(f.ability_key=="reveal")||item.deploy_region!=f.source.region
   ||item.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("JC028角色事务、原帧或实际牌面不符".into());}self.mobility_immutable_identity(c)
 }

}
